#!/usr/bin/env bash
# Majorité, étape 3 — la fiche d'un membre.
# - Majorité : « Majeur d'office » pour Administrateurs, Instructeurs, Bureau ; sinon la date de naissance décide,
#   jamais affichée (« renseignée ✓ », Remplacer) et plus jamais envoyée aux écrans admin ; parent avec téléphone ;
# - Cours donnés (instructeur, lecture seule) et Cours suivis ;
# - Droit à l'image en UNE section : en vigueur usage par usage, demande au parent, formulaires, correction repliée ;
# - guides admin, tutoriel, e2e à jour. Pas de migration.
# Prérequis : apply-majorite-2-creation-compte.sh.
# Usage (racine du repo) : bash apply-majorite-3-fiche-membre.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" 2>/dev/null | grep -qF "LegalStatusControl"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "CreationLegalFields" "apps/web/src/features/admin/users/forms/CreateUserForm.tsx" 2>/dev/null || { echo "lancez d'abord apply-majorite-2-creation-compte.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/admin/droit-image-d-un-mineur.mdx" "apps/web/content/docs/admin/gerer-un-membre.mdx" "apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" "apps/web/src/features/admin/users/components/UsersTable.tsx" "apps/web/src/features/admin/users/courses/CoursesControl.tsx" "apps/web/src/features/docs/entities/procedureMap.generated.json" "apps/web/src/features/tours/definitions/admin.users.droit-image-mineur.ts" "e2e/creation-compte.spec.ts" "e2e/droit-a-l-image.spec.ts" "e2e/groupes-systeme.spec.ts" "packages/backend/src/modules/users/legalInfo.ts" "packages/backend/src/modules/users/router.ts" "apps/web/src/features/admin/users/legal/LegalInfoControl.tsx" "apps/web/src/features/admin/users/legal/LegalInfoFields.tsx")
CREATED=("apps/web/src/features/admin/users/components/ImageRightsSection.tsx" "apps/web/src/features/admin/users/legal/LegalStatusControl.tsx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "LegalStatusControl" "apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/admin/users/components"
